const req = String($json.chatInput ?? $json.text ?? $json.message ?? '').trim();
if (!req) throw new Error('No request received.');

const workspace_path = 'G:/company';

// Scanner: liest .py Dateien, gibt kompaktes JSON auf stdout aus
// Begrenzt auf 14000 Zeichen damit es in Bridge stdout passt
const scannerScript = `import json, os, sys
from pathlib import Path

ws = Path(os.environ.get('PYTHONPATH', '').split(os.pathsep)[0]) if 'PYTHONPATH' in os.environ else Path.cwd()
SKIP = {'.venv','venv','__pycache__','.git','node_modules','.mypy_cache'}
files = []
total = 0
LIMIT = 13000

for root, dirs, fnames in os.walk(ws):
    dirs[:] = [d for d in dirs if d not in SKIP]
    for fname in sorted(fnames):
        p = Path(root) / fname
        if p.suffix not in ('.py', '.json'): continue
        rel = p.relative_to(ws).as_posix()
        if rel.startswith('_scan'): continue
        try:
            content = p.read_text(encoding='utf-8', errors='replace')
            # Kürze große Dateien
            if len(content) > 3000:
                content = content[:3000] + '\\n# [truncated]'
            entry = {'path': rel, 'content': content}
            entry_str = json.dumps(entry)
            if total + len(entry_str) > LIMIT:
                files.append({'path': rel, 'content': '[skipped: size limit]'})
            else:
                files.append(entry)
                total += len(entry_str)
        except Exception as e:
            files.append({'path': rel, 'content': '', 'error': str(e)})

print(json.dumps({'ok': True, 'files': files}))
`;

// Startup-Dummy
const startupDummy = `import sys\nsys.exit(0)\n`;

return [{json:{
  user_request:        req,
  workspace_path,
  scanner_script:      scannerScript,
  startup_dummy:       startupDummy,
  repair_attempts:     0,
  max_repairs:         4,
  analysis_done:       false,
  repair_plan:         [],
  improved_files:      [],
  repair_history:      [],
  repair_loop_done:    false,
  repair_limit_reached: false,
  skipped_repairs:     []
}}];

const s = $node['Parse Project Files'].json;
let raw = $json.body ?? $json.data ?? $json;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch {} }
let result = raw;
if (result?.stage === 'compile' && result?.compile?.ok === false) {
  const err = String(result.compile?.stderr ?? 'Compilation failed');
  result = { ...result, ok: false,
    smoke_result: { ok: false, stderr: 'COMPILE ERROR:\n' + err, stdout: '', exit_code: 1 },
    startup_result: { ok: false, stderr: 'Skipped', stdout: '', exit_code: 1 }
  };
}
return [{json:{...s, initial_test_result: result}}];

const s = $node['Parse Initial Test Result'].json;

let raw = $json.body ?? $json.data ?? $json;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch {} }

let content = raw?.message?.content ?? raw?.content ?? '';
if (typeof content !== 'string') content = JSON.stringify(content ?? raw);
content = content.trim()
  .replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();

function repairJson(text) {
  try { return JSON.parse(text); } catch {}
  try {
    let t = text.trimEnd();
    if ((t.match(/(?<!\\)"/g)||[]).length % 2 !== 0) t += '"';
    const opens = [];
    let inStr = false;
    for (let i=0; i<t.length; i++) {
      const c=t[i], p=t[i-1];
      if(c==='"'&&p!=='\\') inStr=!inStr;
      if(!inStr){if(c==='{')opens.push('}');else if(c==='[')opens.push(']');else if(c==='}' || c===']')opens.pop();}
    }
    t = t.replace(/,\s*$/,'') + opens.reverse().join('');
    return JSON.parse(t);
  } catch {}
  throw new Error('Cannot parse analyst output: ' + text.slice(0,200));
}

const analysis = repairJson(content);

const repairPlan = Array.isArray(analysis.repair_plan)
  ? analysis.repair_plan
      .filter(r => r && r.file && r.instruction)
      .map((r,i) => ({...r, priority: r.priority ?? i+1}))
      .sort((a,b) => a.priority - b.priority)
  : [];

if (!repairPlan.length) {
  throw new Error('Analyst returned empty repair_plan.');
}

// Normalisiere Dateipfade
const norm = p => String(p).replace(/\\/g,'/').replace(/^\.\//,'').trim();
const normalizedPlan = repairPlan.map(r => ({...r, file: norm(r.file)}));

// test_script aus Analyse oder Fallback
const testScript = norm(analysis.test_script ?? s.test_script ?? 'tests/smoke_test.py');
const startupScript = norm(analysis.startup_test_script ?? s.startup_test_script ?? 'tests/startup_test.py');

return [{json:{
  ...s,
  project_summary: String(analysis.project_summary ?? ''),
  architecture_contract: String(analysis.architecture_contract ?? ''),
  issues: Array.isArray(analysis.issues) ? analysis.issues : [],
  repair_plan: normalizedPlan,
  remaining_repairs: [...normalizedPlan],
  test_script: testScript,
  startup_test_script: startupScript,
  analysis_done: true
}}];

const s = $json;

// Helper: normalize file paths (remove leading ./, backslashes, etc.)
const norm = p => String(p ?? '').replace(/\\/g, '/').replace(/^\.\/+/, '').trim();

// All files that were generated by the scanner
const files = Array.isArray(s.generated_files) ? s.generated_files : [];

// Remaining repairs queue
let remaining = Array.isArray(s.remaining_repairs) ? [...s.remaining_repairs] : [];

// If we have reached the max number of repairs – stop immediately
const maxRepairs = Math.max(0, Number(s.max_repairs ?? 4));
const attempts   = Math.max(0, Number(s.repair_attempts ?? 0));

if (attempts >= maxRepairs) {
  return [{
    json: {
      ...s,
      repair_limit_reached: true,
      repair_loop_done: true,
      current_repair: null,
      repair_target: '',
      repair_context: [],
      remaining_repairs: remaining
    }
  }];
}

// Skip invalid / missing entries in the queue (but do not increase attempts)
while (remaining.length > 0) {
  const candidate   = remaining[0];
  const candidatePath = norm(candidate?.file);
  const found = files.find(f => norm(f?.path) === candidatePath);

  if (candidate && candidatePath && found) break;
  remaining = remaining.slice(1);
}

if (!remaining.length) {
  return [{
    json: {
      ...s,
      repair_loop_done: true,
      current_repair: null,
      repair_target: '',
      repair_context: [],
      remaining_repairs: [],
      skipped_repairs: [...(s.skipped_repairs ?? []), ...remaining] // nothing left
    }
  }];
}

// We have a target – pick the first remaining repair
const current    = remaining[0];
let   targetPath = norm(current.file);
let   targetFile = files.find(f => norm(f?.path) === targetPath);

// Fallback: if the target file was not found, use the first file from the scan
if (!targetFile && files.length > 0) {
  targetFile = files[0];
  targetPath = norm(targetFile.path);
}

if (!targetFile) {
  // No file at all – give up for this run
  return [{
    json: {
      ...s,
      repair_loop_done: true,
      current_repair: null,
      repair_target: '',
      repair_context: [],
      remaining_repairs: remaining.slice(1),
      skipped_repairs: [...(s.skipped_repairs ?? []), targetPath]
    }
  }];
}

// Build context: the target file + any imports it declares
const contextFiles = [];
const seen         = new Set([targetPath]);

contextFiles.push({
  path: targetFile.path,
  content: String(targetFile.content ?? ''),
  reason: 'repair target'
});

const importLines = String(targetFile.content ?? '')
  .split('\n')
  .filter(l => /^\s*(from|import)\s+/.test(l));

for (const line of importLines) {
  const m = line.match(
    /^\s*from\s+([\w.]+)\s+import|^\s*import\s+([\w.]+)/
  );
  if (!m) continue;

  const mod = (m[1] || m[2] || '').split('.')[0];
  const candidates = [
    mod + '.py',
    'core/' + mod + '.py',
    'ui/' + mod + '.py',
    'network/' + mod + '.py',
    'utils/' + mod + '.py'
  ];

  for (const c of candidates) {
    const dep = files.find(
      f => norm(f?.path) === c || norm(f?.path).endsWith('/' + mod + '.py')
    );
    if (dep && !seen.has(norm(dep.path))) {
      seen.add(norm(dep.path));
      contextFiles.push({
        path: dep.path,
        content: String(dep.content ?? ''),
        reason: 'dependency'
      });
      break;
    }
  }
}

return [
  {
    json: {
      ...s,
      current_repair: current,
      repair_target: targetPath,
      repair_source: String(targetFile.content ?? ''),
      repair_instruction: String(current.instruction ?? ''),
      repair_reason: String(current.reason ?? ''),
      repair_context: contextFiles,
      remaining_repairs: remaining,
      repair_loop_done: false,
      repair_limit_reached: false
    }
  }
];

const s = $node['Prepare Next Repair'].json;

let raw = $json.body ?? $json.data ?? $json;

if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch { /* bleibt String */ }
}

let source =
  raw?.message?.content ??
  raw?.response ??
  raw?.content ??
  '';

if (typeof source !== 'string') {
  source = JSON.stringify(source ?? '');
}

// Fallback JSON-Wrapper
const trimmed = source.trim();
if (trimmed.startsWith('{')) {
  try {
    const parsed = JSON.parse(trimmed);
    if (typeof parsed?.content === 'string') source = parsed.content;
    else if (typeof parsed?.code === 'string') source = parsed.code;
    else if (typeof parsed?.response === 'string') source = parsed.response;
  } catch { /* kein JSON */ }
}

// Markdown entfernen
source = source
  .trim()
  .replace(/^```(?:python|py|text)?\r?\n?/i, '')
  .replace(/\r?\n?```$/i, '')
  .trim();

// Truncation Recovery
if (!source || source.length < 20) {
  const raw_str = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
  const match = raw_str.match(/"(?:content|code|response)"\s*:\s*"([\s\S]+)/);
  if (match) {
    let extracted = match[1];
    const endQuote = extracted.search(/(?<!\\)"/);
    if (endQuote > 0) extracted = extracted.slice(0, endQuote);
    try { source = JSON.parse('"' + extracted + '"'); }
    catch { source = extracted; }
  }
}

if (!source || source.trim().length < 10) {
  const preview = JSON.stringify(raw).slice(0, 400);
  throw new Error(
    'Repair Coder returned empty or unusable source.\nRaw preview: ' + preview
  );
}

return [{
  json: {
    ...s,
    repair_source: source.trim()
  }
}];

const s = $json;

// Normalisiere den Zielpfad
let target = String(s.repair_target ?? '')
  .replace(/\\/g, '/')
  .replace(/^\.\/+/, '')
  .trim();

// Quelle (Code), der geschrieben werden soll
const source = String(s.repair_source ?? '');

// Falls kein Target vorhanden ist, versuche das erste File des Scan‑Ergebnisses zu nutzen
if (!target && Array.isArray(s.generated_files) && s.generated_files.length > 0) {
  const first = s.generated_files[0].path ?? '';
  target = String(first)
    .replace(/\\/g, '/')
    .replace(/^\.\/+/, '')
    .trim();
}

if (!target) {
  throw new Error(
    'Repair payload invalid: repair_target is empty. Prepare Next Repair did not provide a target file.'
  );
}

// Pfad muss relativ zum Workspace sein
if (
  target.startsWith('/') ||
  /^[A-Za-z]:\\//.test(target) ||
  target.split('/').includes('..')
) {
  throw new Error(
    'Repair payload invalid: repair_target must be a relative workspace path. Got: ' +
      target
  );
}

// Prüfe, ob die Datei im Scan‑Ergebnis vorkommt
const generated = Array.isArray(s.generated_files) ? s.generated_files : [];
const targetExists = generated.some(f =>
  String(f?.path ?? '')
    .replace(/\\/g, '/')
    .replace(/^\.\/+/, '')
    .trim() === target
);

if (!targetExists) {
  throw new Error(
    'Repair payload invalid: target is not present in generated_files: ' + target
  );
}

if (!source.trim()) {
  throw new Error('Repair payload invalid: repair_source is empty.');
}

// Payload für den Bridge‑Aufruf
const bridge_write_payload = {
  action: 'write_file',
  path: target,
  content: source
};

return [
  {
    json: {
      ...s,
      repair_target: target,
      repair_source: source,
      bridge_write_payload,
      bridge_write_payload_json: JSON.stringify(bridge_write_payload)
    }
  }
];

const s = $node['Normalize Repair Output'].json;

let raw = $json.body ?? $json.data ?? $json;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch {}
}

if (raw?.ok === false) {
  throw new Error('Bridge refused write: ' + JSON.stringify(raw));
}

const target = String(s.repair_target ?? '').replace(/\\/g, '/').replace(/^\.\/+/, '').trim();
if (!target) {
  throw new Error('No repair_target available after successful coder output.');
}

const files = (s.generated_files ?? []).map(f =>
  String(f.path ?? '').replace(/\\/g, '/').replace(/^\.\/+/, '').trim() === target
    ? { ...f, content: String(s.repair_source ?? '') }
    : f
);

const queue = Array.isArray(s.remaining_repairs) ? [...s.remaining_repairs] : [];
const first = queue[0];
const firstPath = String(first?.file ?? '').replace(/\\/g, '/').replace(/^\.\/+/, '').trim();

if (firstPath !== target) {
  throw new Error(
    'Repair queue/state mismatch. Queue head=' + firstPath + ', target=' + target
  );
}

const nextQueue = queue.slice(1);
const nextAttempts = Math.max(0, Number(s.repair_attempts ?? 0)) + 1;

return [{
  json: {
    ...s,
    generated_files: files,
    improved_files: [...(s.improved_files ?? []), target],
    remaining_repairs: nextQueue,
    repair_attempts: nextAttempts,
    last_repair: {
      path: target,
      instruction: s.repair_instruction,
      attempt: nextAttempts
    },
    repair_loop_done: nextQueue.length === 0,
    repair_limit_reached: nextAttempts >= Number(s.max_repairs ?? 4)
  }
}];

const s = $node['Parse Analysis'].json;
let raw = $json.body ?? $json.data ?? $json;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch {} }
let result = raw;
if (result?.stage === 'compile' && result?.compile?.ok === false) {
  const err = String(result.compile?.stderr ?? 'Compilation failed');
  result = { ...result, ok: false,
    smoke_result: { ok: false, stderr: 'COMPILE ERROR:\n' + err, stdout: '', exit_code: 1 },
    startup_result: { ok: false, stderr: 'Skipped', stdout: '', exit_code: 1 }
  };
}
return [{json:{...s, final_test_result: result}}];

