const s = $node['Scan Project'].json;

let raw = $json.body ?? $json.data ?? $json;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch {} }

// Debug-Info für Fehlersuche
const compileOk    = raw?.compile?.ok;
const compileErr   = String(raw?.compile?.stderr ?? '');
const smokeStdout  = String(raw?.smoke_result?.stdout ?? '').trim();
const smokeStderr  = String(raw?.smoke_result?.stderr ?? '').trim();
const startupOk    = raw?.startup_result?.ok;

// Compile-Fehler im Scanner selbst
if (compileOk === false) {
  throw new Error('Scanner script has syntax error:\n' + compileErr);
}

// Scanner-Fehler in stderr
if (!smokeStdout && smokeStderr) {
  throw new Error('Scanner failed:\n' + smokeStderr.slice(0, 500));
}

// JSON aus stdout parsen
let scanResult = null;
try {
  const lines = smokeStdout.split('\n').filter(l => l.trim().startsWith('{'));
  if (lines.length > 0) {
    scanResult = JSON.parse(lines[lines.length - 1]);
  }
} catch(e) {
  throw new Error(
    'Cannot parse scanner JSON output.\n' +
    'stdout: ' + smokeStdout.slice(0, 400) + '\n' +
    'stderr: ' + smokeStderr.slice(0, 200)
  );
}

if (!scanResult?.ok || !Array.isArray(scanResult?.files)) {
  throw new Error(
    'Scanner returned no files.\n' +
    'stdout: ' + smokeStdout.slice(0, 400) + '\n' +
    'stderr: ' + smokeStderr.slice(0, 200) + '\n' +
    'compile_ok: ' + compileOk + '\n' +
    'startup_ok: ' + startupOk
  );
}

const files = scanResult.files;
if (!files.length) {
  throw new Error('No files found in workspace: ' + s.workspace_path);
}

const pyFiles     = files.filter(f => f.path.endsWith('.py') && !f.path.startsWith('_scan'));
const testFiles   = pyFiles.filter(f => f.path.includes('test'));
const srcFiles    = pyFiles.filter(f => !f.path.includes('test'));
const configFiles = files.filter(f => f.path.endsWith('.json'));

const smokeTest   = testFiles.find(f => f.path.includes('smoke'))?.path
                 ?? testFiles[0]?.path
                 ?? 'tests/smoke_test.py';
const startupTest = testFiles.find(f => f.path.includes('startup'))?.path
                 ?? testFiles.find(f => f.path !== smokeTest)?.path
                 ?? 'tests/startup_test.py';

const project_context = pyFiles
  .map(f => 'FILE: ' + f.path + '\n' + String(f.content ?? ''))
  .join('\n\n')
  .slice(0, 55000);

return [{json:{
  ...s,
  project_files:       files,
  src_files:           srcFiles.map(f => f.path),
  test_files:          testFiles.map(f => f.path),
  config_files:        configFiles.map(f => f.path),
  generated_files:     files.map(f => ({path: f.path, content: String(f.content ?? '')})),
  test_script:         smokeTest,
  startup_test_script: startupTest,
  project_context,
  file_count:          files.length
}}];

const request = String($json.chatInput ?? $json.text ?? $json.message ?? '').trim();
if (!request) throw new Error('No development request received.');
const workspace_path = 'G:/company';
return [{json:{
  user_request: request,
  workspace_path,
  generated_files: [],
  remaining_files: [],
  repair_attempts: 0,
  max_repairs: 3,
  current_file: null,
  repair_instruction: '',
  test_script: '',
  startup_test_script: '',
  repair_history: []
}}];

const base = $node['Project Settings1'].json;

let raw = $json.body ?? $json.data ?? $json.response ?? $json;

if (typeof raw === 'string') {
  raw = JSON.parse(raw);
}

let content = raw?.message?.content ?? raw?.content;

if (typeof content !== 'string') {
  content = JSON.stringify(content ?? raw);
}

content = content
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const a = JSON.parse(content);

if (!a || typeof a !== 'object' || Array.isArray(a)) {
  throw new Error('Architect did not return an object.');
}

/*
 * Required architecture fields
 */

if (
  typeof a.architecture_contract !== 'string' ||
  !a.architecture_contract.trim()
) {
  throw new Error('Missing architecture_contract.');
}

if (!Array.isArray(a.file_manifest) || !a.file_manifest.length) {
  throw new Error('Missing file_manifest.');
}

/*
 * Path normalization
 */

const norm = p =>
  String(p)
    .replace(/\\/g, '/')
    .replace(/^\.\/+/, '')
    .trim();

/*
 * Normalize manifest
 */

const manifest = a.file_manifest.map((f, index) => {
  if (!f || typeof f !== 'object') {
    throw new Error(
      `Invalid file_manifest entry at index ${index}.`
    );
  }

  const path = norm(f.path);

  if (!path) {
    throw new Error(
      `Missing path in file_manifest entry ${index}.`
    );
  }

  return {
    path,
    purpose: String(f.purpose ?? ''),
    depends_on: Array.isArray(f.depends_on)
      ? f.depends_on.map(norm).filter(Boolean)
      : []
  };
});

const paths = manifest.map(f => f.path);
const pathSet = new Set(paths);

/*
 * Validate project paths
 */

if (new Set(paths).size !== paths.length) {
  const duplicates = paths.filter(
    (p, i) => paths.indexOf(p) !== i
  );
  throw new Error(
    'Duplicate manifest path: ' +
    [...new Set(duplicates)].join(', ')
  );
}

for (const p of paths) {
  if (
    !p ||
    p.startsWith('/') ||
    /^[A-Za-z]:/.test(p) ||
    p.split('/').includes('..') ||
    p.includes('\0')
  ) {
    throw new Error('Unsafe path: ' + p);
  }
}

/*
 * Separate project dependencies from external dependencies.
 */

const externalDependencies = new Set();

for (const file of manifest) {
  const projectDeps = [];
  for (const dep of file.depends_on) {
    if (dep === file.path) continue;
    if (pathSet.has(dep)) {
      projectDeps.push(dep);
    } else {
      externalDependencies.add(dep);
