      .map(p => String(p).replace(/\\/g, '/').replace(/^\.\//, '').trim())
      .filter(Boolean)
  : [];

const normalizedAffected = [
  ...new Set(affectedFiles.filter(p => generated.some(f => f.path === p)))
];

const confidence = String(analysis.confidence ?? 'low').toLowerCase();

const instruction = String(analysis.repair_instruction ?? '').trim();

if (!instruction) {
  throw new Error('Repair Analyst returned no repair_instruction.');
}

return [{
  json: {
    ...s,

    current_file: {
      path: target,
      purpose: 'repair',
      depends_on: []
    },

    repair_source:
      targetFile.content,

    repair_target:
      target,

    repair_architecture_contract:
      s.architecture_contract ?? '',

    repair_root_cause:
      String(analysis.root_cause ?? ''),

    repair_affected_files:
      normalizedAffected,

    repair_instruction:
      instruction,

    repair_confidence:
      ['high', 'medium', 'low'].includes(confidence)
        ? confidence
        : 'low'
  }
}];

const s = $json;

// State-Transfer: Failure Report1 → Scan Project
// Scan Project liest user_request aus chatInput/text/message
// und baut den Scanner-State neu auf.
// Wir reichen user_request durch und setzen alle Loop-Felder zurück.

const user_request = String(
  s.user_request ?? s.chatInput ?? s.text ?? s.message ?? ''
).trim();

if (!user_request) {
  throw new Error(
    'Repair instructor: user_request fehlt im Failure-Report-Output. ' +
    'Failure Report1 muss user_request weiterreichen.'
  );
}

return [{json:{
  // Scan Project liest eines dieser Felder als user_request
  chatInput:           user_request,
  // Kontext für den LGDC-Scan-Loop
  workspace_path:      String(s.workspace_path ?? 'G:/company'),
  // Reparatur-History aus dem vorherigen Lauf mitgeben
  // (wird von Scan Project weitergereicht falls benötigt)
  prior_repair_attempts: Number(s.repair_attempts ?? 0),
  prior_errors:        s.error ?? '',
  prior_test_result:   s.test_result ?? null,
  // Explizit kein analysis_done, keine repair_plan etc. –
  // Scan Project setzt alles frisch auf
}}];
